import{_ as e,o,c as a,a2 as r}from"./chunks/framework.CqdVOxXJ.js";const p=JSON.parse(`{"title":"What's new","description":"","frontmatter":{},"headers":[],"relativePath":"whats-new.md","filePath":"whats-new.md","lastUpdated":1793403538000}`),n={name:"whats-new.md"};function s(i,t,d,h,l,g){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="what-s-new" tabindex="-1">What&#39;s new <a class="header-anchor" href="#what-s-new" aria-label="Permalink to &quot;What&#39;s new&quot;">​</a></h1><p>Changes to Rakkii Ops that this guide now covers. Dates are when the change reached the integration app.</p><h2 id="oct-31-2026" tabindex="-1">Oct 31, 2026 <a class="header-anchor" href="#oct-31-2026" aria-label="Permalink to &quot;Oct 31, 2026&quot;">​</a></h2><h3 id="released-and-done-are-separate" tabindex="-1">Released and Done are separate <a class="header-anchor" href="#released-and-done-are-separate" aria-label="Permalink to &quot;Released and Done are separate&quot;">​</a></h3><ul><li><strong>Released</strong> means the car is out; <strong>Done</strong> (was &quot;Closed&quot;) means nothing is left on the job. The button is <strong>Mark as done</strong> (<a href="/rakkii-cars-guide/chapters/05-lane-1-private-walk-in-jobs#_5-11-mark-the-job-as-done">Chapter 5</a>).</li><li>Only open checklist items block <strong>Mark as done</strong>. Money still owed (for example an insurer payment) is listed but does not block. The Owner can mark it done anyway with a reason, saved in the Status log.</li><li><strong>Job history</strong> has <strong>Released · not done</strong> and <strong>Done</strong> labels and filters, plus a <strong>Progress</strong> column. On a phone each job is a card.</li></ul><h3 id="see-where-a-job-is-at-a-glance" tabindex="-1">See where a job is at a glance <a class="header-anchor" href="#see-where-a-job-is-at-a-glance" aria-label="Permalink to &quot;See where a job is at a glance&quot;">​</a></h3><ul><li>Every job has a <strong>status banner</strong>, a <strong>steps bar</strong> (&quot;Step 6 of 7 · Paid&quot;, tap it for each step&#39;s date) and ✓ / ● marks on the tabs (<a href="/rakkii-cars-guide/chapters/05-lane-1-private-walk-in-jobs#progress">Chapter 5</a>).</li><li>Once the car is out, <strong>Not done yet</strong> lists what is still open: checklist items, balances, unpaid suppliers and a payment proof to review.</li><li>On the <strong>Shop board</strong>, each card has a <strong>What&#39;s left</strong> button that opens the same list without leaving the board (<a href="/rakkii-cars-guide/chapters/10-workshop-operations-board-calendar-backjobs-contractors">Chapter 10</a>).</li><li>The balance reads <strong>Quote ₱…</strong> before work, <strong>To collect ₱…</strong> during work and <strong>Customer owes ₱…</strong> once the car is out.</li></ul><h3 id="dashboard" tabindex="-1">Dashboard <a class="header-anchor" href="#dashboard" aria-label="Permalink to &quot;Dashboard&quot;">​</a></h3><ul><li><strong>Announcements</strong> are at the top, above <strong>Priority jobs</strong>.</li><li>Five figures instead of nineteen: <strong>Cars in shop</strong>, <strong>Ready for pickup</strong>, <strong>On hold</strong>, <strong>Cash in today</strong> and <strong>Overdue invoices</strong>. Empty lists are hidden.</li></ul><h3 id="less-to-think-about-on-the-job-page" tabindex="-1">Less to think about on the job page <a class="header-anchor" href="#less-to-think-about-on-the-job-page" aria-label="Permalink to &quot;Less to think about on the job page&quot;">​</a></h3><ul><li><strong>Print job order</strong> plus a <strong>More papers ▾</strong> menu replace the row of print buttons in the Job order box (<a href="/rakkii-cars-guide/chapters/05-lane-1-private-walk-in-jobs#printing">Chapter 5</a>).</li><li>On a phone, prints save as a PDF named after the paper and plate, for example <code>Gate pass DEMO 101.pdf</code>. The gate pass shows <strong>Released on</strong>, and the acceptance fills <strong>Work completed</strong> by itself.</li><li><strong>Technicians and dates</strong> shows the dates the app recorded (Car in, Started, Done, Car out, Billed, Paid). The date boxes are behind <strong>Edit dates</strong>.</li><li>The technician list shows technicians first; Owner and Admin are behind <strong>Show owner and admin</strong>.</li><li><strong>Send to QC</strong> asks first if checklist steps are still open.</li><li><strong>QC photos</strong> show one tile per angle with a ✓. Upload buttons show only for missing angles; <strong>Replace a photo</strong> and <strong>Show photos</strong> are a tap away (<a href="/rakkii-cars-guide/chapters/02-technician-daily-guide#_2-8-uploading-the-four-qc-photos">Chapter 2</a>).</li><li>The Pay tab has a <strong>Down payment</strong> card in plain words, with the overrides behind <strong>Change the down payment</strong>. <strong>Commission and agent fee</strong> moves to the bottom, folded, and the paper previews are behind <strong>Show … preview</strong>.</li><li>The Quote tab with no lines says to add lines first, with a <strong>Go to Work tab</strong> button.</li></ul><h3 id="other-screens" tabindex="-1">Other screens <a class="header-anchor" href="#other-screens" aria-label="Permalink to &quot;Other screens&quot;">​</a></h3><ul><li><strong>Parts &amp; Inventory</strong> fits on an iPad and laptop without scrolling sideways; the unit sits with On hand (&quot;10 pc&quot;) (<a href="/rakkii-cars-guide/chapters/09-parts-inventory-canvass-restock-payables">Chapter 9</a>).</li><li>On an iPad, the top bar no longer overlaps and the Shop board shows two lanes side by side.</li><li>Customer mobiles can be tapped to call; the customer page has <strong>Call</strong> and <strong>Text</strong> links.</li><li><strong>Finance › Payments › Pending proofs</strong> shows the customer&#39;s mobile.</li></ul><h2 id="oct-29-2026" tabindex="-1">Oct 29, 2026 <a class="header-anchor" href="#oct-29-2026" aria-label="Permalink to &quot;Oct 29, 2026&quot;">​</a></h2><h3 id="jobs-tell-you-what-to-do-next" tabindex="-1">Jobs tell you what to do next <a class="header-anchor" href="#jobs-tell-you-what-to-do-next" aria-label="Permalink to &quot;Jobs tell you what to do next&quot;">​</a></h3><ul><li>Every job shows a <strong>next-step banner</strong> under the plate, for example &quot;Add quote lines, start canvass, or start work.&quot; or &quot;Collect PHP 800.00 from customer before release.&quot; (<a href="/rakkii-cars-guide/chapters/05-lane-1-private-walk-in-jobs#next-step">Chapter 5</a>).</li><li>Technicians get their own banner: &quot;Finish the bay checklist (1 step left), then send to QC.&quot; (<a href="/rakkii-cars-guide/chapters/02-technician-daily-guide">Chapter 2</a>).</li><li>A waiting customer payment proof shows on the banner and on the <strong>Pay</strong> and <strong>Release</strong> tabs, with a link to <strong>Finance › Payments</strong>.</li></ul><h3 id="qc-photos-lock-ready-for-pickup" tabindex="-1">QC photos lock Ready for pickup <a class="header-anchor" href="#qc-photos-lock-ready-for-pickup" aria-label="Permalink to &quot;QC photos lock Ready for pickup&quot;">​</a></h3><ul><li>While QC photos are missing, <strong>Send to QC</strong> is the main button and <strong>Ready for pickup</strong> is greyed out with the reason (&quot;Need 4 QC photos before Ready/Released (have 0).&quot;).</li></ul><h3 id="quotes-and-margin" tabindex="-1">Quotes and margin <a class="header-anchor" href="#quotes-and-margin" aria-label="Permalink to &quot;Quotes and margin&quot;">​</a></h3><ul><li>If work lines change after a quote, the Quote and Work tabs warn &quot;Work lines changed since the last quote…&quot;.</li><li>Margin is labelled <strong>on cost</strong>: (sell − cost) ÷ cost. The shop&#39;s minimum margin uses the same basis.</li></ul><h3 id="insurance" tabindex="-1">Insurance <a class="header-anchor" href="#insurance" aria-label="Permalink to &quot;Insurance&quot;">​</a></h3><ul><li><strong>Waiting for LOA</strong> now offers <strong>Mark authorized</strong>, <strong>Start work (cash / no LOA)</strong>, <strong>Back to quote</strong>, <strong>Put on hold</strong> and <strong>Cancel job</strong> (<a href="/rakkii-cars-guide/chapters/06-lane-2-insurance-claims-and-loa">Chapter 6</a>).</li><li><strong>Release of Claim</strong>, <strong>Print gate pass</strong> and <strong>Print customer invoice</strong> are on the <strong>Release</strong> tab.</li></ul><h3 id="desk" tabindex="-1">Desk <a class="header-anchor" href="#desk" aria-label="Permalink to &quot;Desk&quot;">​</a></h3><ul><li><strong>New job</strong> asks for the customer, car and work first. Picking a customer on file shows their cars as chips to fill the vehicle.</li><li>&quot;Promised date&quot; is now <strong>Target date</strong>. The <strong>Appointment</strong> (when the car comes in) is a separate date.</li><li><strong>Priority jobs</strong> on the Dashboard, a <strong>search box</strong> in the top bar, and a <strong>Customer activity</strong> feed with a bell count (<a href="/rakkii-cars-guide/chapters/10-workshop-operations-board-calendar-backjobs-contractors">Chapter 10</a>).</li><li>Hard-to-undo actions (create quote, post invoice, record payment, release, approve leave) ask you to confirm.</li></ul><h3 id="hr" tabindex="-1">HR <a class="header-anchor" href="#hr" aria-label="Permalink to &quot;HR&quot;">​</a></h3><ul><li><strong>This week</strong> is Monday to Sunday on Attendance, Payroll and My week.</li><li>Dates read &quot;Oct 29, 2026&quot; everywhere; leave ranges read &quot;Oct 26 – 28, 2026&quot;.</li><li>The <strong>Approve leave</strong> dialog lists the person&#39;s open jobs so you can reassign them.</li><li>The public shop email is <strong><a href="mailto:rakkiicars@gmail.com" target="_blank" rel="noreferrer">rakkiicars@gmail.com</a></strong>.</li></ul><h2 id="a-day-in-the-shop-one-job-from-intake-to-release" tabindex="-1">A day in the shop: one job from intake to release <a class="header-anchor" href="#a-day-in-the-shop-one-job-from-intake-to-release" aria-label="Permalink to &quot;A day in the shop: one job from intake to release&quot;">​</a></h2><p>This is the path we tested end to end on the integration app on Oct 29, 2026, with the Owner and a Lead Technician. Follow it to practise.</p><table tabindex="0"><thead><tr><th>#</th><th>Who</th><th>Where</th><th>What</th></tr></thead><tbody><tr><td>1</td><td>Owner</td><td><strong>Workshop › New job</strong></td><td>Customer, mobile, plate, make, model, year → <strong>Create job</strong>. Status <strong>Booked</strong>.</td></tr><tr><td>2</td><td>Owner</td><td>Job › <strong>Work › Work lines</strong></td><td>Add a labor line (Description, Qty, Cost, Sell) → <strong>Add line</strong>.</td></tr><tr><td>3</td><td>Owner</td><td>Job › <strong>Work › Technicians and dates</strong></td><td>Tick the technician → <strong>Save technicians</strong>. The change is in <strong>Assignment history</strong>.</td></tr><tr><td>4</td><td>Owner</td><td>Job › <strong>Create quote</strong></td><td>Confirm. Status <strong>Quoted</strong>, margin chip &quot;Margin 167% on cost&quot;.</td></tr><tr><td>5</td><td>Owner</td><td>Job header</td><td><strong>Start work</strong>. Status <strong>Under repair</strong>; <strong>Ready for pickup</strong> is locked until the QC photos are in.</td></tr><tr><td>6</td><td>Technician</td><td><strong>My jobs</strong> → the plate</td><td>Add and tick a <strong>Bay checklist</strong> step. Banner: &quot;Send the car to QC when the work is done.&quot;</td></tr><tr><td>7</td><td>Technician</td><td>Job header</td><td><strong>Send to QC</strong>. Status <strong>Quality check</strong>.</td></tr><tr><td>8</td><td>Technician</td><td><strong>Work › QC photos</strong></td><td>Upload <strong>Front</strong>, <strong>Rear</strong>, <strong>Left side (LS)</strong>, <strong>Right side (RS)</strong>. Banner: &quot;QC photos are done. The desk marks the car ready for pickup.&quot;</td></tr><tr><td>9</td><td>Technician</td><td><strong>Me › Leave</strong></td><td><strong>Request leave</strong> for a day.</td></tr><tr><td>10</td><td>Owner</td><td><strong>HR › Clock kiosk</strong></td><td>Tap the technician to clock them in; check it in <strong>HR › Attendance</strong>.</td></tr><tr><td>11</td><td>Owner</td><td>Job header</td><td><strong>Ready for pickup</strong>. Banner: &quot;Collect PHP 800.00 from customer before release.&quot;</td></tr><tr><td>12</td><td>Owner</td><td>Job › <strong>Pay</strong></td><td><strong>Bill customer</strong> → <strong>Create invoice</strong>, then <strong>Record payment</strong> (Cash). Customer owes PHP 0.00.</td></tr><tr><td>13</td><td>Owner</td><td>Job › <strong>Release</strong></td><td>Tick <strong>Keys logged</strong>, <strong>Documents in / out</strong>, <strong>Customer signed release</strong> → <strong>Release car</strong>.</td></tr><tr><td>14</td><td>Owner</td><td><strong>HR › Leave approvals</strong></td><td><strong>Approve</strong> the technician&#39;s leave; keep or reassign their open jobs → <strong>Approve leave</strong>.</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Practice data only</p><p>Use made-up customers and plates on the integration app. Never enter real customer names, phone numbers or plates.</p></div>',30)])])}const u=e(n,[["render",s]]);export{p as __pageData,u as default};
